-- One CHECK or DEFAULT per column. test/archlens.test.ts renders each and compares it with
-- what pglast (the Python original's printer) produced for this same file.
CREATE TABLE t (
  a INT, b INT, c INT, d TEXT, tags TEXT[],
  e01 INT CHECK (a + b = 1),
  e02 INT CHECK ((a = 1) AND b = 2),
  e03 INT CHECK (a = 1 OR b = 2 AND c = 3),
  e04 INT CHECK ((a = 1 OR b = 2) AND c = 3),
  e05 INT CHECK (NOT (a = 1 AND b = 2)),
  e06 INT CHECK (NOT a IS NULL),
  e07 INT CHECK (a IN (1, 2)),
  e08 INT CHECK (a NOT IN (1, 2)),
  e09 INT CHECK (a BETWEEN 1 AND 2),
  e10 INT CHECK (a NOT BETWEEN 1 AND 2),
  e11 INT CHECK ((a + b) * c = 6),
  e12 INT CHECK (a + (b * c) = 6),
  e13 INT CHECK (a + b * c = 6),
  e14 INT CHECK (a IS NULL AND b IS NULL),
  e15 INT CHECK (d::text || 'x' <> ''),
  e16 INT CHECK (CAST(a AS text) = d),
  e17 INT CHECK (a::int > -1),
  e18 INT CHECK (-a < 0),
  e19 INT CHECK (COALESCE(a, b, 0) > 0),
  e20 INT CHECK (GREATEST(a, b) > 0),
  e21 INT CHECK (CASE WHEN a = 1 THEN b ELSE c END > 0),
  e22 INT CHECK (CASE a WHEN 1 THEN true ELSE false END),
  e23 INT CHECK (tags[1] <> ''),
  e24 INT CHECK (d LIKE 'x%' OR d ILIKE 'y%'),
  e25 INT CHECK (d IS DISTINCT FROM 'z'),
  e26 INT CHECK (NULLIF(a, 0) IS NOT NULL),
  e27 INT CHECK (a = ANY (ARRAY[1, 2])),
  e28 INT CHECK (length(d) BETWEEN 1 AND 10 AND d <> ''),
  e29 INT CHECK ((a IS NOT NULL)::int + (b IS NOT NULL)::int = 1),
  e30 INT CHECK (NOT (a IS NULL)),
  e31 INT CHECK ((a + b) IS NULL),
  e32 INT CHECK (CAST(a + b AS text) = d),
  e33 INT CHECK ((a IS NULL AND b IS NULL) = true),
  e34 INT CHECK (NOT a = 1),
  e35 INT CHECK (- (a + b) < 0),
  e36 INT CHECK (a - -1 > 0),
  e37 INT CHECK ((tags[1:2])[1] <> ''),
  e38 INT CHECK (LEAST(a, b) > 0),
  e39 INT CHECK ((a, b) IS DISTINCT FROM (1, 2)),
  e40 INT CHECK (d COLLATE "C" = 'x'),
  e41 TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP(3),
  e42 INT CHECK (a IN (1)),
  f01 TIMESTAMPTZ DEFAULT now() - interval '1 day',
  f02 TEXT DEFAULT 'a' || 'b',
  f03 INT DEFAULT (1 + 2) * 3,
  f04 NUMERIC DEFAULT 1e3,
  f05 TEXT DEFAULT E'x\ny',
  f06 INT DEFAULT +1,
  f07 BOOLEAN DEFAULT (NOT true),
  f08 TEXT DEFAULT current_user,
  f09 JSONB DEFAULT '{}'::jsonb,
  f10 NUMERIC(14,2) DEFAULT 0,
  f11 TEXT DEFAULT 'it''s'
);
